package ma.autocarnet;
import org.json.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
final class FinanceReport {
 static LocalDate start(String p){return p.matches("[0-9]{4}")?Year.parse(p).atDay(1):YearMonth.parse(p).atDay(1);}
 static LocalDate next(String p){return start(p).plusMonths(p.length()==4?12:1);}
 static class Row {String type;double paid,allocated;Row(String t){type=t;}}
 static class Result {Map<String,Row> rows=new TreeMap<>();double paid,allocated,km;boolean partial,unknown;int missing;List<String> segments=new ArrayList<>();Row row(String t){return rows.computeIfAbsent(t,Row::new);}}
 static boolean doc(String t){return Arrays.asList("insurance","vignette","inspection").contains(t);}
 static double interval(JSONObject data,JSONObject e)throws Exception{JSONObject p=e.optJSONObject("oilPlan");return Math.max(1,p==null?data.getJSONObject("vehicle").optDouble("oilInterval",10000):p.optDouble("km",10000));}
 static Double rate(JSONObject data,List<JSONObject> all,JSONObject point)throws Exception{List<JSONObject> oils=new ArrayList<>();for(JSONObject e:all)if(e.optString("type").equals("oil")&&(e.getString("date").compareTo(point.getString("date"))<0||(e.getString("date").equals(point.getString("date"))&&e.getDouble("km")<=point.getDouble("km"))))oils.add(e);if(oils.isEmpty())return null;JSONObject last=oils.get(oils.size()-1);JSONArray lines=last.optJSONArray("serviceLines");if(lines==null||lines.length()==0)return last.getDouble("cost")/interval(data,last);Map<String,Double> rates=new HashMap<>();for(JSONObject e:oils){JSONArray products=e.optJSONArray("serviceLines");if(products==null)continue;Map<String,Double> group=new HashMap<>();for(int i=0;i<products.length();i++){JSONObject x=products.getJSONObject(i);String key=x.optString("serviceKey","other");if(key.equals("other")){key=x.optString("reference");if(key.isEmpty())key=x.getString("name");key=key.trim().toLowerCase(Locale.ROOT);}double r=x.getDouble("quantity")*x.getDouble("unitPrice")/(interval(data,e)*x.optInt("everyOil",1));group.put(key,group.getOrDefault(key,0d)+r);}rates.putAll(group);}JSONObject t=last.optJSONObject("trace");double r=t==null?0:(t.optDouble("labor",0)+t.optDouble("fees",0))/interval(data,last);for(double x:rates.values())r+=x;return r;}
 static Result calculate(JSONObject data,String period)throws Exception{Result r=new Result();String from=start(period).toString(),to=next(period).toString(),end=next(period).minusDays(1).toString();List<JSONObject> all=ReportPdf.entries(data);boolean hasOil=false;for(JSONObject e:all){String type=e.getString("type"),date=e.getString("date");double cost=e.getDouble("cost");if(type.equals("oil")&&date.compareTo(to)<0)hasOil=true;if(date.compareTo(from)>=0&&date.compareTo(to)<0){r.row(type).paid+=cost;if(!doc(type)&&!type.equals("oil"))r.row(type).allocated+=cost;if(doc(type)&&(!e.has("coverageStart")||!e.has("coverageEnd")))r.missing++;}if(doc(type)&&e.has("coverageStart")&&e.has("coverageEnd")){String a=e.getString("coverageStart"),b=e.getString("coverageEnd"),lo=a.compareTo(from)>0?a:from,hi=b.compareTo(end)<0?b:end;if(lo.compareTo(hi)<=0)r.row(type).allocated+=cost*(ChronoUnit.DAYS.between(LocalDate.parse(lo),LocalDate.parse(hi))+1)/(ChronoUnit.DAYS.between(LocalDate.parse(a),LocalDate.parse(b))+1);}}
 double oil=0;JSONObject v=data.getJSONObject("vehicle");for(int i=0;i<(period.length()==4?12:1);i++){String a=start(period).plusMonths(i).toString(),b=start(period).plusMonths(i+1).toString();List<JSONObject> points=new ArrayList<>();JSONObject baseline=new JSONObject().put("date",v.getString("baselineDate")).put("km",v.getDouble("baselineKm"));List<JSONObject> candidates=new ArrayList<>(all);candidates.add(baseline);for(JSONObject e:candidates)if(e.optBoolean("hasKm",true)&&e.getString("date").compareTo(a)>=0&&e.getString("date").compareTo(b)<=0)points.add(e);points.sort(Comparator.comparing((JSONObject e)->e.optString("date")).thenComparingDouble(e->e.optDouble("km")));Set<Double> startKms=new HashSet<>(),endKms=new HashSet<>();for(JSONObject p:points){if(p.getString("date").equals(a))startKms.add(p.getDouble("km"));if(p.getString("date").equals(b))endKms.add(p.getDouble("km"));}boolean ambiguous=startKms.size()>1||endKms.size()>1;if(!endKms.isEmpty()){double minEnd=Collections.min(endKms);points.removeIf(p->p.optString("date").equals(b)&&p.optDouble("km")!=minEnd);}double amount=0,km=0;boolean unknown=false;for(int j=1;j<points.size();j++){JSONObject prev=points.get(j-1),curr=points.get(j);double delta=curr.getDouble("km")-prev.getDouble("km");if(delta<0){unknown=true;continue;}km+=delta;if(delta>0){Double rate=rate(data,all,prev);if(rate==null)unknown=true;else amount+=delta*rate;}}boolean partial=ambiguous||points.size()<2||!points.get(0).getString("date").equals(a)||!points.get(points.size()-1).getString("date").equals(b);r.partial|=partial;r.unknown|=unknown;r.km+=km;if(!unknown)oil+=amount;r.segments.add(a.substring(0,7)+" : "+ReportPdf.num(km)+" km / "+(unknown?"inconnu":ReportPdf.num(amount)+" DH")+(partial?" (période partielle)":""));}if(hasOil||oil>0)r.row("oil").allocated=oil;for(Row row:r.rows.values()){r.paid+=row.paid;r.allocated+=row.allocated;}return r;}
 static void append(ReportPdf.Layout pdf,JSONObject data,String period)throws Exception{Result r=calculate(data,period);RoadReport.finance(pdf,data,period,r.paid);pdf.heading("Bilan financier unifié");pdf.row("Total réellement payé",ReportPdf.num(r.paid)+" DH");pdf.row("Coût réparti estimatif — ne pas additionner au payé",ReportPdf.num(r.allocated)+" DH");pdf.paragraph("Documents : montant réparti sur les jours de validité. Vidange : estimation par km et fréquence de chaque produit. Autres frais, y compris carburant : achats de la période, pas consommation physique du mois. Les deux totaux représentent deux lectures différentes des mêmes coûts.",6);pdf.paragraph(r.partial||r.unknown||r.missing>0?"CALCUL PARTIEL : dates de validité ou compteurs manquants. Les montants inconnus ne sont pas inventés. Contrats payés sans validité : "+r.missing+". Les frais non saisis restent inconnus.":"Calcul selon les périodes et compteurs renseignés. La part vidange reste estimative, notamment si la durée impose un remplacement anticipé.",4);for(Row row:r.rows.values())if(row.paid!=0||row.allocated!=0){pdf.row(LABEL(row.type)+" · payé",ReportPdf.num(row.paid)+" DH");pdf.row(LABEL(row.type)+" · réparti",ReportPdf.num(row.allocated)+" DH");}pdf.heading("Sources des répartitions");for(JSONObject e:ReportPdf.entries(data)){String type=e.optString("type");if(doc(type)&&e.has("coverageStart")&&e.has("coverageEnd")&&e.getString("coverageStart").compareTo(next(period).toString())<0&&e.getString("coverageEnd").compareTo(start(period).toString())>=0)pdf.paragraph(LABEL(type)+" · paiement "+e.getString("date")+" : "+ReportPdf.num(e.getDouble("cost"))+" DH · validité "+e.getString("coverageStart")+" → "+e.getString("coverageEnd")+" · référence opération : "+e.optString("id"),4);}
 pdf.heading("Part vidange estimée sur les relevés");pdf.paragraph("Prix / (intervalle km × fréquence en vidanges) × km relevés. Main-d’œuvre et frais inclus dans le cycle. Les périodes manquantes ne sont pas extrapolées ; les cycles ne sont pas régularisés rétroactivement.",4);for(String s:r.segments)pdf.paragraph(s,2);
 pdf.heading("Historique source des prix de vidange");pdf.paragraph("Références de calcul uniquement : ces achats historiques ne sont pas ajoutés aux paiements de cette période. Le dernier achat connu de chaque catégorie fournit le prix estimatif.",4);
 for(JSONObject e:ReportPdf.entries(data))if(e.optString("type").equals("oil")&&e.getString("date").compareTo(next(period).toString())<0){pdf.paragraph(e.getString("date")+" · "+ReportPdf.num(e.getDouble("km"))+" km · facture "+ReportPdf.num(e.getDouble("cost"))+" DH · référence : "+e.optString("id"),3);JSONArray products=e.optJSONArray("serviceLines");if(products!=null)for(int i=0;i<products.length();i++){JSONObject x=products.getJSONObject(i);pdf.paragraph(x.getString("name")+" · "+x.optString("reference")+" · "+ReportPdf.num(x.getDouble("quantity"))+" × "+ReportPdf.num(x.getDouble("unitPrice"))+" DH · fréquence : "+x.optInt("everyOil",1)+" vidange(s)",3);}JSONObject t=e.optJSONObject("trace");if(t!=null&&t.optBoolean("breakdown"))pdf.paragraph("Main-d’œuvre : "+ReportPdf.num(t.optDouble("labor",0))+" DH · autres frais : "+ReportPdf.num(t.optDouble("fees",0))+" DH (déjà inclus)",3);pdf.paragraph("Intervalle saisi : "+ReportPdf.num(interval(data,e))+" km",2);}

 }
 static String LABEL(String t){return ReportPdf.LABELS.getOrDefault(t,t);}
}
